#include <iostream>
#include <vector>
#include <algorithm>
#include <deque>

using namespace std;

typedef long long ll;

// Helper to calculate ceil(h/A)
ll ceil_div(ll h, ll A) {
    return (h + A - 1) / A;
}

// Returns true if there exists a position p that defeats at least k enemies within A attacks
bool check(ll A, int n, ll m, int k, const vector<ll>& h, const vector<ll>& x) {
    vector<ll> L(n), R(n);
    deque<int> maxL_dq, minR_dq;

    for (int i = 0; i < n; ++i) {
        ll d = ceil_div(h[i], A);
        if (d > m) {
            // Cannot be defeated with A attacks. Interval is empty.
            // We mark it as invalid.
            L[i] = 2e18; 
            R[i] = -2e18;
        } else {
            ll reach = m - d;
            L[i] = x[i] - reach;
            R[i] = x[i] + reach;
        }
    }

    // We need to find a point p that is covered by at least k intervals.
    // Since we only care about existence, we can use a sweep-line or check intersections.
    // However, the sliding window approach for contiguous is flawed.
    // Correct approach: Collect all valid intersection points?
    // Actually, the constraint is "at least k".
    // The number of valid intervals can be up to N.
    // We need to find if there is a point covered by at least k.
    // This can be done by considering all L and R endpoints.
    // Events: L[i] -> enter interval (+1), R[i] -> leave interval (-1).
    // Sort events. Sweep.

    vector<pair<ll, int>> events;
    events.reserve(2 * n);
    for (int i = 0; i < n; ++i) {
        if (R[i] >= L[i]) { // Valid interval
            events.push_back({L[i], 1});
            events.push_back({R[i], -1});
        }
    }
    sort(events.begin(), events.end());

    int current_overlap = 0;
    for (auto &ev : events) {
        current_overlap += ev.second;
        if (current_overlap >= k) return true;
    }
    return false;
}

void solve() {
    int n, k;
    ll m;
    if (!(cin >> n >> m >> k)) return;
    vector<ll> h(n), x(n);
    for (int i = 0; i < n; ++i) cin >> h[i];
    for (int i = 0; i < n; ++i) cin >> x[i];

    ll low = 0, high = 1000000000000LL; // Max possible answer
    ll ans = -1;

    while (low <= high) {
        ll mid = low + (high - low) / 2;
        if (mid == 0) { low = mid + 1; continue; } // Avoid div by 0
        if (check(mid, n, m, k, h, x)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    cout << ans << "\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        solve();
    }
    return 0;
}
